'use strict';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const paths={overview:'Tổng quan',players:'Người chơi',catalog:'Kho vật phẩm',gacha:'Gacha & vòng quay',giftcodes:'Giftcode',events:'Sự kiện',calendar:'Lịch sự kiện',audit:'Nhật ký hoạt động',provenance:'Nguồn và bản dịch'};
