const icon=(name,cls='')=>`<svg viewBox="0 0 24 24" class="${cls}" aria-hidden="true"><path d="${drawings[name]||drawings.box}"/></svg>`;
const sourceLabels={'longzhidao-client':'Client Long Chi Đảo · không phải ENG','eng-client':'Client ENG gốc','eng-client-vietnamese':'Tiếng Việt gốc ENG','new-vietnamese-translation':'Bản dịch Việt bổ sung · không có sẵn trong ENG','original-ios-compatibility':'IPA gốc · giữ tương thích','no-text':'Không có văn bản','source-text-untranslated':'Văn bản nguồn chưa dịch'};
const navIcons={provenance:'info',overview:'grid',players:'users',catalog:'box',gacha:'spark',giftcodes:'gift',events:'flag',calendar:'calendar',audit:'activity'};
const state={token:sessionStorage.getItem('db2.admin.token')||'',route:'overview',page:1,q:'',type:'',color:'',status:'',eventTab:'custom',month:new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Ho_Chi_Minh'})),pool:102,seq:0,events:[],templates:[],eventMetrics:[{id:'none',label:'Quà theo lịch'}],pools:[],wheel:[],items:new Map(),audit:[],giftcodes:[]};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>new Intl.NumberFormat('vi-VN').format(n||0), plain=v=>String(v??'').replace(/<[^>]*>/g,'');
const date=(n,opts={})=>!n?'—':new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',day:'2-digit',month:'2-digit',year:'numeric',...opts}).format(new Date(n*1000));
const time=n=>date(n,{hour:'2-digit',minute:'2-digit'}), shortTime=n=>new Intl.DateTimeFormat('vi-VN',{timeZone:'Asia/Ho_Chi_Minh',hour:'2-digit',minute:'2-digit'}).format(new Date(n*1000));
const toInput=n=>new Date(n*1000+7*3600000).toISOString().slice(0,16), fromInput=s=>s?Math.floor(new Date(s+':00+07:00').getTime()/1000):0;
const typeNames={role:'Nhân vật',money:'Tiền & vé',soul:'Mảnh tướng',artifact:'Bảo vật',box:'Rương',ship:'Chiến hạm',capsule:'Capsule',fruit:'Trái sức mạnh',starSign:'Cung mệnh',item:'Nguyên liệu',eqpt:'Trang bị',title:'Danh hiệu',frame:'Khung ảnh',chatSkin:'Khung chat'};
const badge=(s,label)=>`<span class="badge ${esc(s)}">${s==='active'||s==='online'?'<i class="dot"></i>':''}${esc(label||({active:'Đang mở',scheduled:'Sắp diễn ra',paused:'Tạm dừng',ended:'Đã kết thúc',expired:'Hết hạn',exhausted:'Hết lượt',online:'Online'}[s]||s))}</span>`;
const btn=(label,ic,action,extra='',cls='')=>`<button type="button" class="btn ${cls}" data-act="${action}" ${extra}>${ic?icon(ic):''}${esc(label)}</button>`;
function itemImage(it,cls=''){return `<span class="item-image ${cls}" aria-hidden="true">${it?.image?`<img src="${esc(it.image)}" width="56" height="56" alt="" loading="lazy">`:icon(it?.type==='role'?'users':it?.type==='money'?'diamond':it?.type==='box'?'gift':'box')}</span>`}
function cacheItems(items){for(const r of items||[])state.items.set(Number(r.id),r)}
function known(id){return state.items.get(Number(id))||{id:Number(id),name:'Vật phẩm #'+id,type:'item'}}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='',4500)}
async function api(path='/admin/api',body){const r=await fetch(path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+state.token,...(body?{'Content-Type':'application/json'}:{})},...(body?{body:JSON.stringify(body)}:{})});let d;try{d=await r.json()}catch{d={error:r.status===401?'Token quản trị không đúng.':'Không thể đọc dữ liệu server.'}}if(!r.ok){if(r.status===401&&state.token){state.token='';sessionStorage.removeItem('db2.admin.token');$('#app').hidden=true;$('#login').hidden=false}throw Error(d.error||'Không thể thực hiện thao tác.')}return d}
async function prime(rewards){const ids=[...new Set((rewards||[]).map(r=>Number(r.entityId)))];await Promise.all(ids.filter(id=>!state.items.has(id)).map(async id=>{const it=await api('/admin/catalog/'+id);state.items.set(id,it)}))}
const empty=(title,text,action='')=>`<div class="empty">${icon('box')}<h3>${esc(title)}</h3><p>${esc(text)}</p>${action}</div>`;
function head(title,subtitle,actions='',eyebrow='VẬN HÀNH MÁY CHỦ'){return `<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div><div class="head-actions">${actions}</div></div>`}
function search(placeholder,value=state.q){return `<div class="search">${icon('search')}<input id="searchInput" aria-label="${esc(placeholder)}" placeholder="${esc(placeholder)}" value="${esc(value)}" autocomplete="off"></div>`}
function pager(d){return `<div class="pager"><span>${num(d.total)} kết quả · Trang ${d.page}/${d.pages}</span><div class="pager-buttons">${btn('Trước','left','page',`data-page="${d.page-1}" ${d.page<=1?'disabled':''}`,'small')}<span>${d.page}</span>${btn('Tiếp','chevron','page',`data-page="${d.page+1}" ${d.page>=d.pages?'disabled':''}`,'small')}</div></div>`}
function nav(){ $('#nav').innerHTML=Object.entries(paths).map(([k,v])=>`<a href="#${k}" ${state.route===k?'aria-current="page"':''}>${icon(navIcons[k])}<span>${v}</span></a>`).join('');$('#breadcrumb').textContent=paths[state.route];$('#serverGlyph').innerHTML=icon('server');$('#refresh').innerHTML=icon('refresh');$('#menuToggle').innerHTML=icon('menu');$('#closeModal').innerHTML=icon('close') }
function connection(ok){const dot='<i class="dot" style="background:var(--'+(ok?'green':'red')+')"></i>';$('#serverConnection').innerHTML=dot+' '+(ok?'Đang hoạt động':'Mất kết nối');$('#topLive').innerHTML=dot+' '+(ok?'Trực tiếp':'Ngoại tuyến');$('#topLive').style.color=ok?'var(--green)':'var(--red)'}
async function load(){if(!state.token)return;const seq=++state.seq;nav();const r=state.route;if($('#view').dataset.route!==r||!$('#view').children.length){$('#view').innerHTML='<div class="loading" role="status"><span class="spinner" aria-hidden="true"></span>Đang tải dữ liệu server…</div>';$('#view').dataset.route=r}$('#view').setAttribute('aria-busy','true');try{let html='';const qs=new URLSearchParams({q:state.q,page:state.page,limit:r==='catalog'?24:20,type:state.type,color:state.color,status:state.status});
if(r==='overview'){const [d,c]=await Promise.all([api('/admin/overview'),api('/admin/catalog?limit=6&type=artifact')]);cacheItems(c.items);html=overview(d,c.items)}
if(r==='provenance'){html=sourceView(await api('/admin/provenance'))}
if(r==='players'){const d=await api('/admin/players?'+qs);html=players(d)}
if(r==='catalog'){const d=await api('/admin/catalog?'+qs);cacheItems(d.items);html=catalog(d)}
if(r==='events'){const d=await api('/admin/events');state.events=d.events;state.templates=d.templates;state.eventMetrics=d.eventMetrics||state.eventMetrics;cacheItems(d.rewardItems);await prime(d.events.flatMap(e=>e.rewards));html=events(d)}
if(r==='calendar'){const d=await api('/admin/events');state.events=d.events;state.templates=d.templates;state.eventMetrics=d.eventMetrics||state.eventMetrics;cacheItems(d.rewardItems);const y=state.month.getFullYear(),m=state.month.getMonth(),a=Math.floor(Date.UTC(y,m,1)/1000)-7*3600-7*86400,b=Math.floor(Date.UTC(y,m+1,1)/1000)-7*3600+7*86400;const c=await api('/admin/calendar?start='+a+'&end='+b);html=calendar(c.items)}
if(r==='gacha'){const d=await api('/admin/gacha');state.pools=d.pools;state.wheel=d.wheelPrizes;for(const p of d.pools)cacheItems(p.entries.map(e=>e.item));cacheItems(d.wheelPrizes.map(e=>e.item));html=gacha(d)}
if(r==='giftcodes'){const d=await api('/admin/giftcodes');state.giftcodes=d.items;await prime(d.items.flatMap(e=>e.rewards));html=codes(d.items)}
if(r==='audit'){const d=await api('/admin/audit?limit=25&page='+state.page+'&action='+encodeURIComponent(state.type));state.audit=d.items;html=audit(d)}
if(seq!==state.seq)return;connection(true);const focused=document.activeElement?.id==='searchInput'?{start:document.activeElement.selectionStart,end:document.activeElement.selectionEnd}:null;$('#view').innerHTML=html;if(focused&&$('#searchInput')){$('#searchInput').focus();$('#searchInput').setSelectionRange(focused.start,focused.end)}$('#view').removeAttribute('aria-busy');$('#sidebarSync').textContent='Cập nhật lúc '+shortTime(Date.now()/1000);$('#footerSync').textContent='Đồng bộ '+shortTime(Date.now()/1000)+' · UTC+7';$('#topTime').textContent=date(Date.now()/1000);bindFilters();}catch(e){if(seq===state.seq){connection(false);$('#view').innerHTML=empty('Chưa tải được dữ liệu',e.message,btn('Thử lại','refresh','reload'));toast(e.message,true)}}}
function overview(d,items){const s=d.stats;const peak=Math.max(1,...d.series.map(s=>s.count));const cards=[['Người chơi','users',num(s.players),`${s.online} đang online`,'green'],['Sự kiện đang mở','flag',num(s.activeEvents+s.builtinOpen),s.activeEvents+' tùy chỉnh · '+s.builtinOpen+' hệ thống','amber'],['Lượt gacha hôm nay','spark',num(s.draws24h),'Trong 24 giờ gần nhất','blue'],['Vật phẩm trong dữ liệu','box',num(s.items),'Từ danh mục client Android','purple']];return head('Tổng quan máy chủ','Một góc nhìn rõ ràng về thế giới DB2 của bạn.',btn('Lịch sự kiện','calendar','go',`data-route="calendar"`)+btn('Tạo sự kiện','plus','event-new','','primary'),'DB2 PRIVATE / OPERATIONS')+`<div class="stats">${cards.map(([l,i,n,t,c])=>`<article class="stat"><div class="stat-label">${l}<span class="stat-icon ${c}">${icon(i)}</span></div><div class="stat-number">${n}</div><div class="stat-note"><span class="dot" style="background:var(--${c})"></span>${t}</div></article>`).join('')}</div><div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>Nhịp hoạt động</h2><p>Hoạt động được server ghi nhận trong 7 ngày</p></div>${badge('golden','7 ngày gần đây')}</div><div class="panel-body"><div class="activity-bars">${d.series.map(x=>`<div class="bar-column"><div class="bar" style="height:${Math.max(3,x.count/peak*78)}px" title="${esc(x.date)}: ${x.count} hoạt động"></div><small>${x.date.slice(8)}/${x.date.slice(5,7)}</small></div>`).join('')}</div><div class="subline"><i class="dot" style="background:var(--amber)"></i>${num(d.series.reduce((a,b)=>a+b.count,0))} hoạt động trong tuần</div></div><div class="panel-head" style="border-top:1px solid var(--border)"><h2>Người chơi gần đây</h2><a href="#players">Xem tất cả ${icon('arrow')}</a></div>${playerTable(d.recentPlayers,true)}</section><section class="panel"><div class="panel-head"><div><h2>Sắp diễn ra</h2><p>Lịch sự kiện được bạn thiết lập</p></div><a href="#calendar">${icon('arrow')}</a></div><div class="panel-body">${d.upcomingEvents.length?d.upcomingEvents.map(eventSummary).join(''):empty('Sẵn sàng cho sự kiện mới','Chưa có sự kiện tùy chỉnh nào trong lịch.',btn('Tạo sự kiện','plus','event-new','','small'))}</div><div class="panel-head" style="border-top:1px solid var(--border)"><h2>Hoạt động mới nhất</h2><a href="#audit">${icon('arrow')}</a></div><div class="panel-body">${d.recentAudit.slice(0,4).map(feed).join('')||'<p class="muted">Chưa có hoạt động.</p>'}</div></section></div><section class="panel"><div class="panel-head"><div><h2>Khám phá vật phẩm</h2><p>ID, thông số và phần thưởng — đúng với dữ liệu game</p></div><a href="#catalog">Mở danh mục ${icon('arrow')}</a></div><div class="catalog-preview">${items.map(it=>`<button class="preview-item" data-act="item" data-id="${it.id}">${itemImage(it)}<strong>${esc(it.name)}</strong><small class="mono">#${it.id}</small></button>`).join('')}</div></section>${s.errors24h?`<div class="notice">${icon('info')}<div><strong>${s.errors24h} lỗi client trong 24 giờ</strong><br>Kiểm tra nhật ký để xem thông báo và stack lỗi. <a class="inline-link" href="#audit">Mở nhật ký</a></div></div>`:''}`}
const actionNames={draw:'Quay gacha',create_player:'Tạo nhân vật',rename:'Đổi tên đội',client_error:'Lỗi client',redeem:'Đổi giftcode',claim_events:'Nhận thưởng sự kiện',starter_tickets:'Cấp vé khởi đầu',admin_event_save:'Lưu sự kiện',admin_event_toggle:'Đổi trạng thái sự kiện',admin_activity_config:'Cập nhật event hệ thống',admin_giftcode_save:'Lưu giftcode',admin_player_update:'Chỉnh tài nguyên',admin_grant_items:'Cấp vật phẩm',admin_send_mail:'Gửi thư hệ thống',gacha_entry:'Chỉnh pool gacha',giftcode:'Tạo giftcode',grant:'Cấp gem',profile_migration:'Đồng bộ hồ sơ'};
function actionName(a){return actionNames[a]||a.replace(/^admin_/,'').replaceAll('_',' ')}
function feed(a){return `<div class="feed-row"><span class="feed-symbol ${a.action==='client_error'?'red':''}">${icon(a.action==='client_error'?'info':'activity')}</span><div><strong>${esc(actionName(a.action))}</strong><p>${esc(a.parsed?.player?'Nhân vật #'+a.parsed.player:a.parsed?.name||a.parsed?.code||'Đã ghi nhận trên server')}</p></div><time>${shortTime(a.created)}</time></div>`}
function eventSummary(e){const d=new Date(e.window.start*1000+7*3600000);return `<div class="upcoming-event"><div class="date-tile"><small>T${d.getUTCMonth()+1}</small><strong>${d.getUTCDate()}</strong></div><div class="event-summary"><h3>${esc(e.name)}</h3><p>${shortTime(e.window.start)} – ${shortTime(e.window.end)} · ${e.repeat==='daily'?'Mỗi ngày':e.repeat==='weekly'?'Mỗi tuần':'Một lần'}</p></div>${badge(e.status)}</div>`}
function playerTable(rows,compact=false){return rows.length?`<div class="table-wrap"><table><thead><tr><th>NGƯỜI CHƠI</th><th>CẤP / VIP</th><th>GEM</th>${compact?'':'<th>COIN</th><th>LỰC CHIẾN</th>'}<th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><button type="button" class="player-cell player-link" data-act="player" data-id="${p.id}"><span class="avatar">${esc(p.name.slice(0,2).toUpperCase())}</span><div><strong>${esc(p.name)}</strong><small>#${p.id} · ${esc(p.userName)}</small></div></button></td><td>Lv.${p.level} <span class="muted">/ V${p.vip}</span></td><td class="amber mono">${num(p.gem)}</td>${compact?'':`<td class="mono">${num(p.coin)}</td><td class="mono">${num(p.power)}</td>`}<td>${p.online?badge('online'):badge('paused','Offline')}</td><td>${btn('Chi tiết','chevron','player',`data-id="${p.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có người chơi','Nhân vật tạo trong game sẽ xuất hiện ở đây.')}
function players(d){return head('Người chơi','Tra cứu hồ sơ, túi đồ và gửi phần thưởng trực tiếp.',btn('Gửi thư','mail','mail'))+`<section class="panel"><div class="toolbar">${search('Tìm tên, tài khoản hoặc player ID…')}<select id="statusFilter" aria-label="Trạng thái người chơi"><option value="">Tất cả trạng thái</option><option value="online" ${state.status==='online'?'selected':''}>Đang online</option></select><span class="toolbar-label">${num(d.total)} người chơi</span></div>${playerTable(d.items)}${pager(d)}</section>`}
function catalog(d){return head('Kho vật phẩm','Tra cứu toàn bộ vật phẩm, nhân vật và dữ liệu gốc của game.',btn('Cấp vật phẩm','gift','grant','','primary'))+`<div class="panel"><div class="toolbar">${search('Tìm tên hoặc item ID, ví dụ 119…')}<select id="typeFilter" aria-label="Lọc loại vật phẩm"><option value="">Tất cả loại vật phẩm</option>${Object.entries(d.types).map(([k,n])=>`<option value="${esc(k)}" ${state.type===k?'selected':''}>${esc(typeNames[k]||k)} (${n})</option>`).join('')}</select><select id="colorFilter" aria-label="Lọc phẩm màu"><option value="">Tất cả phẩm màu</option>${(d.colors||[]).map(i=>`<option value="${i}" ${state.color==i?'selected':''}>Phẩm màu ${i}</option>`).join('')}</select></div></div><div class="filters"><span class="toolbar-label">${num(d.total)} vật phẩm</span><span class="badge">Dữ liệu client thực</span></div><div class="catalog-grid">${d.items.map(it=>`<button class="item-card" data-act="item" data-id="${it.id}"><div class="item-card-top">${itemImage(it)}<span class="badge">${esc(typeNames[it.type]||it.type)}</span></div><h3>${esc(it.name)}</h3><div class="item-id mono">#${it.id}</div><div class="item-card-bottom"><span>Phẩm ${it.color}</span><span>Xem thông số ${icon('arrow')}</span></div></button>`).join('')}</div>${!d.items.length?empty('Không tìm thấy vật phẩm','Thử ID hoặc tên khác, hoặc bỏ bớt bộ lọc.'):''}<div class="panel" style="margin-top:19px">${pager(d)}</div>`}
function eventLoot(event){return (event.rewardGroups||[{label:'Phần thưởng',items:event.rewards||[]}]).flatMap(g=>g.items.map(r=>({...r,group:g.label})))}
function rewardPreview(event,limit=4){const loot=eventLoot(event);if(!loot.length)return `<p class="event-reward-note">${esc(event.id==='privateSpWish'?'Chỉnh giá quay, lượt mỗi ngày và bảo hiểm SP.':'Chưa có phần thưởng cố định để xem trước.')}</p>`;return `<div class="event-rewards" aria-label="Phần thưởng sự kiện">${loot.slice(0,limit).map(r=>{const it=known(r.entityId);return `<div class="event-reward" title="${esc(r.group+' · '+plain(it.description))}">${itemImage(it,'mini')}<span><strong>${esc(it.name)}</strong><small>#${r.entityId} · ${esc(r.group)}</small></span><b>×${num(r.count)}</b></div>`}).join('')}${loot.length>limit?`<p class="event-reward-note">+${loot.length-limit} phần thưởng · Xem trong Chỉnh sửa</p>`:''}</div>`}
function events(d){
 const custom=state.eventTab==='custom',all=custom?d.events:d.templates,q=state.q.toLocaleLowerCase('vi');
 const rows=all.filter(e=>(!q||[e.id,e.name||e.title,e.objectiveLabel||'',...eventLoot(e).map(r=>known(r.entityId).name+' '+r.entityId)].join(' ').toLocaleLowerCase('vi').includes(q))&&(!state.status||(custom?e.status:(e.open?'active':'paused'))===state.status));
 return head('Sự kiện trong game','Chọn vật phẩm bằng ảnh, chỉnh phần thưởng và lịch chạy trên cùng server.',btn('Xem lịch','calendar','go','data-route="calendar"')+btn('Tạo sự kiện','plus','event-new','','primary'))+
 `<div class="tabs"><button class="${custom?'selected':''}" data-act="event-tab" data-tab="custom">Sự kiện tùy chỉnh <span class="muted">${d.events.length}</span></button><button class="${!custom?'selected':''}" data-act="event-tab" data-tab="builtin">Event hệ thống <span class="muted">${d.templates.length}</span></button></div><div class="toolbar event-toolbar">${search('Tìm tên sự kiện, item hoặc ID…')}<select id="statusFilter" aria-label="Trạng thái sự kiện"><option value="">Mọi trạng thái</option>${(custom?[['active','Đang mở'],['scheduled','Sắp diễn ra'],['paused','Tạm dừng'],['ended','Đã kết thúc']]:[['active','Đang mở'],['paused','Đang đóng']]).map(([v,l])=>`<option value="${v}" ${state.status===v?'selected':''}>${l}</option>`).join('')}</select><span class="muted">${rows.length}/${all.length} sự kiện</span></div>`+
 (!custom?`<div class="notice">${icon('info')}<div>Ảnh và số lượng lấy từ bảng thưởng đang dùng trên server. Các mốc, lựa chọn và ô quay là những điều kiện khác nhau; không phải nhận tất cả trong một lượt.</div></div>`:'')+
 `<div class="event-grid">${rows.map(e=>`<article class="event-card" data-event-id="${esc(e.id)}"><div class="event-card-top"><span class="event-mark">${icon(e.id.startsWith('dial:')?'spark':custom?'gift':'flag')}</span>${custom?badge(e.status):badge(e.open?'active':'paused',e.open?'Đang mở':'Đang đóng')}</div><h3>${esc(custom?e.name:e.title)}</h3><p>${esc(plain(e.description||({daily:'Làm mới hằng ngày',weekly:'Tiến độ hằng tuần',lifetime:'Tiến độ thường trực'}[e.period]||'Sự kiện phần thưởng do bạn thiết lập')))}</p><div class="event-meta">${icon('clock')}<span>${custom?time(e.window.start):e.schedule?time(e.schedule.start):({daily:'Mỗi ngày',weekly:'Mỗi tuần',lifetime:'Thường trực'}[e.period])}</span></div>${custom&&e.requirement?.metric!=='none'?`<div class="event-objective">${icon('activity')}<span>${esc(e.objectiveLabel)}</span></div>`:''}${rewardPreview(e)}<div class="event-card-footer"><small>${custom?num(e.claims)+' lượt đã nhận':e.rewardGroups?.length?e.rewardGroups.length+' nhóm thưởng':'Có thiết lập nâng cao'}</small>${btn('Chỉnh sửa','edit',custom?'event-edit':'template-edit',`data-id="${esc(e.id)}"`,'small')}</div></article>`).join('')}</div>`+
 (!rows.length?empty(all.length?'Không có sự kiện khớp bộ lọc':'Một sự kiện mới bắt đầu từ đây',all.length?'Đổi tên, ID hoặc trạng thái để tìm lại.':'Tạo lịch, chọn vật phẩm và đặt thời gian mở cho người chơi.',!all.length&&custom?btn('Tạo sự kiện đầu tiên','plus','event-new','','primary'):''):'');
}
function calendarMobile(items,y,m){let out='';for(let day=1;day<=new Date(y,m+1,0).getDate();day++){const a=Date.UTC(y,m,day)/1000-7*3600,rows=items.filter(e=>e.start<a+86400&&e.end>a);if(!rows.length)continue;out+=`<div class="mobile-calendar-day"><h3>${date(a)}</h3>${rows.map(e=>`<button class="calendar-event ${e.enabled?'':'disabled'}" data-act="${e.source==='builtin'?'template-edit':'event-edit'}" data-id="${esc(e.id)}"><span>${esc(e.name)}</span><small>${shortTime(e.start)} – ${shortTime(e.end)}</small></button>`).join('')}</div>`}return out||empty('Chưa có sự kiện trong tháng','Tạo một sự kiện hoặc chuyển sang tháng khác.')}
function calendar(items){const y=state.month.getFullYear(),m=state.month.getMonth();let first=new Date(Date.UTC(y,m,1));first.setUTCDate(first.getUTCDate()-((first.getUTCDay()+6)%7));const today=new Date(Date.now()+7*3600000).toISOString().slice(0,10);return head('Lịch sự kiện','Giờ Việt Nam · UTC+7. Các kỳ lặp dùng cùng lịch ở server.',btn('Tạo sự kiện','plus','event-new','','primary'))+`<section class="panel"><div class="calendar-toolbar"><h2>Tháng ${m+1}, ${y}</h2><div class="head-actions">${btn('Hôm nay','','month-today','','small')}${btn('Trước','left','month','data-step="-1"','small')}${btn('Tiếp','chevron','month','data-step="1"','small')}</div></div><div class="calendar-days">${['THỨ HAI','THỨ BA','THỨ TƯ','THỨ NĂM','THỨ SÁU','THỨ BẢY','CHỦ NHẬT'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${Array.from({length:42},(_,i)=>{const day=new Date(first.getTime()+i*86400000),a=day.getTime()/1000-7*3600,b=a+86400,events=items.filter(e=>e.start<b&&e.end>a),iso=day.toISOString().slice(0,10);return `<div class="calendar-cell ${day.getUTCMonth()!==m?'other':''}"><span class="calendar-date ${iso===today?'today':''}">${day.getUTCDate()}</span>${events.slice(0,3).map(e=>`<button class="calendar-event ${e.enabled?'':'disabled'}" data-act="${e.source==='builtin'?'template-edit':'event-edit'}" data-id="${esc(e.id)}" title="${esc(e.name)} · ${shortTime(e.start)}">${esc(e.name)}</button>`).join('')}${events.length>3?`<button class="calendar-more" data-act="calendar-day" data-start="${a}">+${events.length-3} sự kiện</button>`:''}</div>`}).join('')}</div><div class="calendar-list">${calendarMobile(items,y,m)}</div></section><div class="notice">${icon('info')}<div>Lịch hiển thị sự kiện tùy chỉnh và lịch riêng của event hệ thống. Các chu kỳ mặc định được quản lý trong <a href="#events" class="inline-link">Sự kiện → Event hệ thống</a>.</div></div>`}
function gacha(d){const p=d.pools.find(p=>p.id===state.pool)||d.pools[0];return head('Gacha & vòng quay','Điều chỉnh phần thưởng, trọng số và xem tỉ lệ thực tế.',btn('Bảng 8 ô vòng quay','spark','wheel'))+`<div class="pool-grid">${d.pools.map(p=>`<button class="pool-choice ${p.id===state.pool?'selected':''}" data-act="pool" data-id="${p.id}"><span class="amber">${icon('spark')}</span><strong>${esc(p.name)}</strong><small>Pool #${p.id} · ${p.custom?p.entries.length+' phần thưởng':'Bảng gốc client'}</small></button>`).join('')}</div><section class="panel"><div class="panel-head"><div><h2>${esc(p.name)} <span class="muted mono">#${p.id}</span></h2><p>${p.custom?'Tỉ lệ = trọng số / tổng trọng số. Tùy chỉnh thay thế cả bảo hiểm của bảng gốc.':'Đang dùng cấu trúc drop và bảo hiểm mặc định từ client.'}</p></div><div class="head-actions">${p.custom?btn('Bảng gốc','refresh','pool-reset',`data-id="${p.id}"`,'small'):''}${btn('Thêm phần thưởng','plus','pool-add','','primary small')}</div></div>${p.custom?`<div class="table-wrap"><table><thead><tr><th>PHẦN THƯỞNG</th><th>SỐ LƯỢNG</th><th>TRỌNG SỐ</th><th>TỈ LỆ</th><th></th></tr></thead><tbody>${p.entries.map(r=>`<tr><td><div class="player-cell">${itemImage(r.item,'mini')}<div><strong>${esc(r.item.name)}</strong><small class="mono">#${r.entityId}${r.extra?.star?' · '+r.extra.star+' sao':''}</small></div></div></td><td>${num(r.count)}</td><td class="mono">${num(r.weight)}</td><td><div class="probability"><span class="probability-track"><i style="width:${r.probability*100}%"></i></span><span>${new Intl.NumberFormat('vi-VN',{style:'percent',maximumSignificantDigits:6}).format(r.probability)}</span></div></td><td><div class="table-actions">${btn('Sửa','edit','pool-edit',`data-id="${r.entityId}"`,'small')}${btn('Xóa','trash','pool-remove',`data-id="${r.entityId}"`,'small subtle')}</div></td></tr>`).join('')}</tbody></table></div>`:empty('Đang dùng bảng gốc','Chỉ chuyển sang tùy chỉnh khi thêm phần thưởng. Mỗi lượt của pool tùy chỉnh chọn một mục theo trọng số.',btn('Tạo phần thưởng tùy chỉnh','plus','pool-add','','primary'))}</section><details><summary>Xem các dòng tham chiếu của bảng drop gốc</summary><pre>${esc(JSON.stringify(p.sourceRows,null,2))}</pre></details>`}
function codes(rows){return head('Giftcode','Mã quà tặng có thời hạn và giới hạn lượt sử dụng.',btn('Tạo giftcode','plus','code-new','','primary'))+`<section class="panel"><div class="toolbar">${search('Tìm mã giftcode…')}<span class="toolbar-label">${rows.length} mã trong server</span></div><div class="table-wrap"><table><thead><tr><th>GIFT CODE</th><th>PHẦN THƯỞNG</th><th>ĐÃ SỬ DỤNG</th><th>HẾT HẠN</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${rows.filter(r=>r.code.toLowerCase().includes(state.q.toLowerCase())).map(r=>`<tr><td><strong class="mono">${esc(r.code)}</strong></td><td><div class="head-actions">${r.gem?`<span class="amber">${num(r.gem)} gem</span>`:''}${r.rewards.slice(0,3).map(x=>`<span title="${esc(known(x.entityId).name)} ×${x.count}">${itemImage(known(x.entityId),'mini')}</span>`).join('')}</div></td><td>${num(r.used)} <span class="muted">/ ${num(r.max_uses)}</span></td><td>${date(r.expires)}</td><td>${badge(r.status)}</td><td>${btn('Chỉnh sửa','edit','code-edit',`data-id="${esc(r.code)}"`,'small')}</td></tr>`).join('')}</tbody></table></div>${!rows.length?empty('Chưa có giftcode','Tặng vé, vật phẩm và gem bằng một mã dùng một lần cho mỗi nhân vật.'):''}</section>`}
function audit(d){return head('Nhật ký hoạt động','Theo dõi các thay đổi quản trị và thông báo từ game.')+`<section class="panel"><div class="toolbar"><select id="typeFilter" aria-label="Lọc loại nhật ký"><option value="">Tất cả hoạt động</option>${d.actions.map(a=>`<option value="${esc(a)}" ${state.type===a?'selected':''}>${esc(actionName(a))}</option>`).join('')}</select><span class="toolbar-label">${num(d.total)} bản ghi</span></div><div class="table-wrap"><table><thead><tr><th>THỜI GIAN</th><th>HOẠT ĐỘNG</th><th>CHI TIẾT</th><th></th></tr></thead><tbody>${d.items.map(r=>`<tr><td>${time(r.created)}<small class="muted"> · #${r.id}</small></td><td><span class="${r.action==='client_error'?'red':''}">${esc(actionName(r.action))}</span></td><td><div class="audit-detail">${esc(plain(JSON.stringify(r.parsed)).slice(0,95))}</div></td><td>${btn('Xem','chevron','audit-detail',`data-id="${r.id}"`,'small')}</td></tr>`).join('')}</tbody></table></div>${!d.items.length?empty('Chưa có bản ghi','Hoạt động mới sẽ được ghi nhận tại đây.'):''}${pager(d)}</section>`}
function bindFilters(){const input=$('#searchInput');if(input)input.oninput=()=>{state.q=input.value;state.page=1;clearTimeout(bindFilters.timer);bindFilters.timer=setTimeout(load,350)};for(const [id,key]of[['typeFilter','type'],['colorFilter','color'],['statusFilter','status']]){const e=$('#'+id);if(e)e.onchange=()=>{state[key]=e.value;state.page=1;load()}}}
function modal(title,body,eyebrow='DB2 OPERATIONS'){ $('#modalTitle').textContent=title;$('#modalEyebrow').textContent=eyebrow;$('#modalBody').innerHTML=body;if(!$('#modal').open)$('#modal').showModal();$('#modalBody input:not([type=hidden]):not(:disabled)')?.focus({preventScroll:true})}
const field=(label,name,type,value='',hint='',attrs='')=>`<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}>${hint?`<small>${esc(hint)}</small>`:''}</label>`;
const select=(label,name,values,value)=>`<label class="field">${esc(label)}<select name="${name}">${values.map(([v,l])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;
function form(body,label='Lưu thay đổi'){return `<form id="editForm">${body}<p class="form-error" role="alert"></p><div class="form-footer">${btn('Hủy','','modal-close')}<button class="btn primary" type="submit">${icon('check')}${esc(label)}</button></div></form>`}
function submitForm(handler){$('#editForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=$('button[type=submit]',f),error=$('.form-error',f);b.disabled=true;error.textContent='';try{await handler(f);$('#modal').close();toast('Đã lưu và đồng bộ với server.');await load()}catch(err){error.textContent=err.message;error.scrollIntoView({block:'nearest'});}finally{b.disabled=false}}}
const values=f=>Object.fromEntries(new FormData(f));let rowSeq=0;
let pickerSerial=0;
function selectedReward(it){return `<div class="reward-picked">${itemImage(it,'mini')}<span><strong>${esc(it?.name||'Chưa chọn vật phẩm')}</strong><small>${it?'#'+it.id+' · '+esc(typeNames[it.type]||it.type):'Tìm theo tên hoặc ID ở dưới'}</small></span></div>`}
function rewardRow(r={entityId:119,count:1,extra:{}}){const it=known(r.entityId),list='reward-picker-'+(++pickerSerial);return `<div class="reward-row" data-reward-row><div class="item-picker"><div data-reward-preview>${selectedReward(it)}</div><input type="hidden" class="reward-id" value="${Number(r.entityId)}"><div class="picker-search-row"><input data-picker-search value="${esc(it.name)} · #${r.entityId}" aria-label="Tìm vật phẩm theo tên hoặc ID" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${list}" autocomplete="off"><button type="button" class="icon-button" data-act="reward-browse" aria-label="Mở danh sách vật phẩm">${icon('search')}</button></div><div id="${list}" class="picker-results" role="listbox" aria-label="Vật phẩm phù hợp" hidden></div></div><label class="reward-field"><span>Số lượng</span><input class="reward-count" aria-label="Số lượng vật phẩm" type="number" inputmode="numeric" min="1" max="1000000" value="${r.count||1}" required></label><label class="reward-field"><span>Sao tướng</span><input class="reward-star" ${it.type!=='role'?'disabled':''} aria-label="Sao của tướng" title="Sao của tướng (vật phẩm khác bỏ qua)" type="number" inputmode="numeric" min="1" max="7" value="${r.extra?.star||1}"></label><button type="button" class="icon-button reward-delete" data-act="reward-remove" aria-label="Bỏ vật phẩm">${icon('close')}</button></div>`}
function rewardSet(id,items){return `<div id="${id}" class="reward-set">${items.map(rewardRow).join('')}</div>${btn('Thêm vật phẩm','plus','reward-add',`data-target="${id}"`,'small subtle')}`}
function readRewards(root){return $$('.reward-row',typeof root==='string'?$(root):root).map(row=>{const id=Number($('.reward-id',row).value),it=known(id);return {entityId:id,count:Number($('.reward-count',row).value),extra:it.type==='role'?{star:Number($('.reward-star',row).value)}:{}}})}
async function eventEditor(id){if(!state.events.length&&!state.templates.length){const d=await api('/admin/events');state.events=d.events;state.templates=d.templates;state.eventMetrics=d.eventMetrics||state.eventMetrics;cacheItems(d.rewardItems)}const e=state.events.find(x=>x.id===id),now=Math.floor(Date.now()/1000),loot=e?.rewards||[{entityId:119,count:1,extra:{}}],goal=e?.requirement||{metric:'none',target:0};await prime(loot);modal(e?'Chỉnh sửa sự kiện':'Một sự kiện mới',form(`<div class="form-grid">${field('ID sự kiện','id','text',e?.id||'EVT_'+Date.now().toString(36).toUpperCase(),'ID được giữ cố định để bảo toàn lịch sử nhận thưởng.',`${e?'readonly':''} required maxlength="64"`)}${field('Tên hiển thị trong quản trị','name','text',e?.name||'','', 'required maxlength="100"')}${field('Bắt đầu · UTC+7','start','datetime-local',toInput(e?.start||now+3600),'','required')}${field('Kết thúc kỳ đầu · UTC+7','end','datetime-local',toInput(e?.end||now+7200),'','required')}${select('Chu kỳ lặp','repeat',[['none','Không lặp'],['daily','Mỗi ngày'],['weekly','Mỗi tuần']],e?.repeat||'none')}${field('Dừng lặp sau · không bắt buộc','until','datetime-local',e?.until?toInput(e.until):'')}${field('Cấp tối thiểu','minLevel','number',e?.minLevel||1,'','min="1" max="200" required')}${field('Thứ tự ưu tiên','priority','number',e?.priority||200,'Số lớn hơn được ưu tiên trong dữ liệu sự kiện.','min="1" max="10000" required')}${select('Điều kiện nhận quà','eventMetric',state.eventMetrics.map(x=>[x.id,x.label]),goal.metric)}<div id="eventGoal">${field('Mốc nhận quà','eventTarget','number',goal.target||1,'Tính tiến độ trong mỗi kỳ chạy của sự kiện.','min="1" max="1000000000" required')}</div></div><label class="field">Mô tả trong game<textarea name="description" maxlength="1000">${esc(e?.description||'')}</textarea></label><label class="check"><input name="enabled" type="checkbox" ${e?.enabled!==false?'checked':''}> Bật sự kiện theo lịch</label><div class="form-section">Phần thưởng mỗi kỳ ${badge('','Nhận 1 lần / nhân vật')}</div>${rewardSet('eventRewards',loot)}<div class="notice">${icon('info')}<span>Đổi thưởng không đặt lại lượt đã nhận. Với sự kiện lặp, mỗi kỳ chạy có lượt nhận độc lập.</span></div>`));submitForm(async f=>{const v=values(f);await api('/admin/api',{action:'event_save',version:e?.version||0,id:v.id,name:v.name,start:fromInput(v.start),end:fromInput(v.end),until:fromInput(v.until),repeat:v.repeat,enabled:f.elements.enabled.checked,description:v.description,minLevel:Number(v.minLevel),priority:Number(v.priority),requirement:{metric:v.eventMetric,target:v.eventMetric==='none'?0:Number(v.eventTarget)},rewards:readRewards('#eventRewards')})});const updateGoal=()=>{const needed=$('[name=eventMetric]').value!=='none';$('#eventGoal').hidden=!needed;$('[name=eventTarget]').disabled=!needed};$('[name=eventMetric]').onchange=updateGoal;updateGoal();if(e){const bar=document.createElement('div');bar.className='head-actions';bar.style.marginTop='18px';bar.innerHTML=btn(e.enabled===false?'Bật lại':'Tạm dừng',e.enabled===false?'play':'pause','event-toggle',`data-id="${esc(e.id)}"`,'small')+btn('Lưu trữ sự kiện','trash','event-delete',`data-id="${esc(e.id)}"`,'small danger');$('#modalBody').append(bar)}}
function needText(values){const names={playerLevel:'Cấp nhân vật',vipLevel:'Cấp VIP',saveGemUpgradeLevelSaveGem:'Gem đã gửi',saveGemUpgradeLevelCount:'Số lần gửi gem',taskActivePoint:'Điểm năng động',loginDays2:'Ngày đăng nhập',selected:'Đã chọn quà',dreamRollTimes:'Lượt xúc xắc',nextReceiveWaitTime:'Thời điểm nhận kế tiếp'};return Object.entries(values).map(([k,v])=>(names[k]||(k.startsWith('buyGoods_')?'Đã mua gói #'+k.slice(9):k))+': '+(k==='nextReceiveWaitTime'&&v?time(v/1000):num(v))).join(' · ')}
async function templateEditor(id){const t=state.templates.find(x=>x.id===id);if(!t)return;await prime(eventLoot(t));const schedule=t.schedule||{start:Math.floor(Date.now()/1000),end:Math.floor(Date.now()/1000)+86400,repeat:'none',until:0};let advanced='';if(id.startsWith('dial:'))advanced=`<div class="form-section">Phần thưởng có thể nhận ở 8 ô quay</div>${rewardPreview(t,8)}<p class="muted">Bảng này dùng chung cho các vòng quay. Chỉnh trong Gacha & vòng quay → Bảng 8 ô vòng quay.</p>`;if(id==='privateSpWish')advanced=`<div class="form-section">Thiết lập điều ước SP</div><div class="form-grid">${field('Gem / lượt','costGem','number',t.options.costGem,'','min="1" max="100000" required')}${field('Lượt bằng gem / ngày','dailyGemLimit','number',t.options.dailyGemLimit,'','min="1" max="1000" required')}${field('Bảo hiểm sau số lượt','maxLuck','number',t.options.maxLuck,'','min="2" max="1000" required')}</div>`;
if(id.startsWith('scorePoint'))advanced=`<div class="form-section">5 mốc điểm & rương thưởng</div>${t.options.scores.map((score,i)=>`<div class="reward-group">${field('Mốc điểm '+(i+1),'score_'+i,'number',score,'','min="1" required')}${rewardSet('box_'+i,t.options.boxes[i])}</div>`).join('')}`;
if(id==='privateSelect')advanced=`<div class="form-section">3 lựa chọn quà trong game</div>${t.options.choices.map((items,i)=>`<div class="reward-group"><div class="form-section">Lựa chọn ${i+1}</div>${rewardSet('choice_'+i,items)}</div>`).join('')}`;
if(id==='dream')advanced=`<div class="form-section">Nhóm thưởng các ô thường</div>${t.options.tiles.map((items,i)=>`<div class="reward-group"><div class="form-section">Nhóm ${i+1}</div>${rewardSet('tile_'+i,items)}</div>`).join('')}<div class="form-section">Thưởng qua một vòng</div>${rewardSet('lapRewards',t.options.lap)}`;
modal(t.title,form(`<div class="notice">${icon('info')}<span>${esc(t.clientVisibility)}. Điều kiện hoàn thành và tiến độ ${t.period==='weekly'?'tuần':t.period==='daily'?'ngày':'thường trực'} được giữ theo luật server.</span></div><label class="check"><input name="enabled" type="checkbox" ${t.enabled?'checked':''}> Cho phép hoạt động / nhận thưởng</label><label class="field">Mô tả trong game<textarea name="description" maxlength="1000">${esc(t.description)}</textarea></label><label class="check"><input name="useSchedule" type="checkbox" ${t.schedule?'checked':''} id="useSchedule"> Dùng lịch chạy riêng</label><div id="scheduleFields" ${!t.schedule?'hidden':''}><div class="form-grid">${field('Bắt đầu · UTC+7','start','datetime-local',toInput(schedule.start))}${field('Kết thúc · UTC+7','end','datetime-local',toInput(schedule.end))}${select('Lặp','repeat',[['none','Không lặp'],['daily','Mỗi ngày'],['weekly','Mỗi tuần']],schedule.repeat)}${field('Dừng lặp sau','until','datetime-local',schedule.until?toInput(schedule.until):'')}</div></div>${t.rewards.length?`<div class="form-section">Các mốc thưởng</div>${t.rewards.map((r,i)=>`<details class="reward-group" ${i===0?'open':''}><summary>Mốc ${i+1} · ${esc(needText(r.needMap))}</summary>${rewardSet('builtinReward_'+i,r.items)}</details>`).join('')}`:''}${advanced}`),'EVENT HỆ THỐNG · '+id);$('#useSchedule').onchange=e=>$('#scheduleFields').hidden=!e.target.checked;submitForm(async f=>{const v=values(f),b={action:'activity_config',id,version:t.version,enabled:f.elements.enabled.checked,description:v.description};if(f.elements.useSchedule.checked)b.schedule={start:fromInput(v.start),end:fromInput(v.end),repeat:v.repeat,until:fromInput(v.until)};if(t.rewards.length)b.rewards=t.rewards.map((_,i)=>readRewards('#builtinReward_'+i));if(id==='privateSpWish')b.options={costGem:Number(v.costGem),dailyGemLimit:Number(v.dailyGemLimit),maxLuck:Number(v.maxLuck)};if(id.startsWith('scorePoint'))b.options={scores:t.options.scores.map((_,i)=>Number(v['score_'+i])),boxes:t.options.boxes.map((_,i)=>readRewards('#box_'+i))};if(id==='privateSelect')b.options={choices:t.options.choices.map((_,i)=>readRewards('#choice_'+i))};if(id==='dream')b.options={tiles:t.options.tiles.map((_,i)=>readRewards('#tile_'+i)),lap:readRewards('#lapRewards')};await api('/admin/api',b)})}
function sourceView(d){return head('Nguồn và bản dịch','Gameplay ENG, tướng S/SS/SSS/SP và phần server mình tự viết.')+`<div class="stats-grid"><div class="stat-card"><small>Bản dữ liệu</small><strong>ENG · SSS/SP</strong><span>34 bảng gốc · không trộn luật Long Chi Đảo</span></div><div class="stat-card"><small>Tiếng Việt gốc ENG</small><strong>${num(d.localization.source_eng_entries)}</strong><span>Giữ riêng từ điển gốc</span></div><div class="stat-card"><small>Bản dịch bổ sung</small><strong>${num(d.localization.authored_entries)}</strong><span>Không gán là bản dịch gốc ENG</span></div></div><section class="panel"><div class="section-head"><h2>Nguồn dữ liệu và luật</h2></div><div style="padding:20px"><p>Backend Python do dự án viết để tương thích giao thức. Không có source backend gốc ENG hoặc Long Chi Đảo. Quy tắc chỉ nằm ở server gốc được ghi là luật riêng.</p><p class="muted">${esc(d.source.game)} · SHA-256 bundle nguồn: <code>${esc(d.source.bundle_sha256||d.source.apk_sha256)}</code></p>${d.privateRules.map(r=>`<article style="padding:16px 0;border-top:1px solid var(--border)"><p>${badge(r.source.startsWith('private-')?'amber':'',d.legend[r.source]||r.source)}</p><p style="margin-top:10px">${esc(r.description)}</p></article>`).join('')}</div></section><section class="panel"><div class="section-head"><h2>Định nghĩa giữ tương thích dữ liệu cũ</h2></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Nguồn</th><th>Lý do</th></tr></thead><tbody>${d.compatibilityDefinitions.map(r=>`<tr><td><button class="btn small" data-act="item" data-id="${r.kindId}">#${r.kindId}</button></td><td>${esc(d.legend[r.source]||r.source)}</td><td>Định nghĩa hộp từ IPA gốc để giữ tương thích; gameplay ENG không đổi.</td></tr>`).join('')}</tbody></table></div></section>`;}
async function itemDetail(id){const it=await api('/admin/catalog/'+id);state.items.set(Number(id),it);modal(it.name,`<div class="detail-hero">${itemImage(it,'large')}<div>${badge('',typeNames[it.type]||it.type)}<h3 style="margin-top:12px">${esc(it.name)}</h3><p class="mono muted">Item ID ${it.id} · Image ID ${esc(it.imgId)}</p></div></div><p class="muted" style="font-size:12px">${esc(plain(it.description)||'Không có mô tả trong bảng dữ liệu.')}</p><div class="detail-grid"><div class="detail-stat"><small>Phẩm màu</small><strong>${it.color}</strong></div><div class="detail-stat"><small>Giá trong bảng gốc</small><strong>${num(it.price)}</strong></div><div class="detail-stat"><small>Giới hạn một ô</small><strong>${it.maxStack<0?'Không giới hạn':it.maxStack}</strong></div></div><section class="panel" style="padding:14px;margin:14px 0"><p><strong>Nguồn dữ liệu:</strong> ${esc(sourceLabels[it.dataSource]||it.dataSource)}</p><p><strong>Tên Việt:</strong> ${esc(sourceLabels[it.translationSource?.name]||it.translationSource?.name)}</p><p><strong>Mô tả Việt:</strong> ${esc(sourceLabels[it.translationSource?.description]||it.translationSource?.description)}</p>${it.grade?`<p><strong>Phẩm tướng:</strong> ${esc(it.grade)} · theo group gốc, giữ nguyên ID</p>`:""}</section><table class="key-values">${Object.entries(it.definition).filter(([k,v])=>!['kindName','desc','kindId'].includes(k)).map(([k,v])=>`<tr><td>${esc(k)}</td><td><code>${esc(typeof v==='object'?JSON.stringify(v):v)}</code></td></tr>`).join('')}</table><div class="form-footer">${btn('Sao chép ID','copy','copy',`data-value="${it.id}"`)}${btn('Cấp vật phẩm này','gift','grant',`data-item="${it.id}"`,'primary')}</div>`,'DANH MỤC VẬT PHẨM · #'+id)}
async function playerDetail(id){const d=await api('/admin/players/'+id),p=d.player;state.detail=d;cacheItems([...d.bag,...d.team]);modal(p.name,`<div class="detail-hero"><span class="avatar" style="width:58px;height:58px;font-size:18px">${esc(p.name.slice(0,2).toUpperCase())}</span><div><h3>${esc(p.name)}</h3><small>#${p.id} · ${esc(p.userName)} · Lv.${p.level} / VIP ${p.vip}</small></div>${p.online?badge('online'):badge('paused','Offline')}</div><div class="detail-grid">${[['Gem',p.gem],['Coin',p.coin],['Thể lực',p.actionPoint],['Điểm kỹ năng',p.skillPoint],['Lực chiến',p.power],['Quyền GM',p.privateGM?'Có':'Không']].map(([k,v])=>`<div class="detail-stat"><small>${k}</small><strong>${typeof v==='number'?num(v):v}</strong></div>`).join('')}</div><div class="head-actions">${btn('Chỉnh tài nguyên','edit','player-update',`data-id="${p.id}"`)}${btn('Cấp vật phẩm','gift','grant',`data-player="${p.id}"`,'primary')}${btn('Gửi thư','mail','mail',`data-player="${p.id}"`)}${btn(p.privateGM?'Thu hồi GM':'Cấp quyền GM','shield','gm',`data-id="${p.id}" data-enabled="${!p.privateGM}"`,'subtle')}</div><div class="form-section">Đội hình · ${d.team.length} nhân vật</div><div class="instance-list">${d.team.map(r=>instance(r,'team')).join('')}</div><div class="form-section">Túi đồ · ${d.bag.length} ô</div><div class="instance-list">${d.bag.map(r=>instance(r,'bag')).join('')||'<p class="muted">Túi đồ trống.</p>'}</div><details><summary>Dữ liệu hồ sơ đầy đủ</summary><pre>${esc(JSON.stringify(d.profile,null,2))}</pre></details>`,'HỒ SƠ NGƯỜI CHƠI · #'+id)}
function instance(r,source){return `<button class="instance-item" data-act="instance" data-source="${source}" data-slot="${esc(r.slot)}" style="text-align:left;background:transparent">${itemImage(r,'mini')}<div><strong>${esc(r.instance.kindName||r.name)}</strong><small>#${r.id} · ${r.type==='role'?'Lv.'+r.instance.level+' / '+r.instance.star+' sao':'×'+num(r.count)}</small></div></button>`}
function instanceDetail(source,slot){const row=state.detail?.[source]?.find(r=>String(r.slot)===String(slot));if(!row)throw Error('Hãy mở lại hồ sơ để lấy dữ liệu mới.');const pid=state.detail.player.id,names={kindId:'Item ID',idx:'Ô trong túi/đội',count:'Số lượng',star:'Sao',level:'Cấp',experience:'Kinh nghiệm',nextLevelExp:'EXP cấp kế',skillLevel:'Cấp kỹ năng',power:'Lực chiến',attr:'Chỉ số hiện tại',initAttr:'Chỉ số ban đầu',skillInfo:'Thuộc tính capsule',cacheSkillInfo:'Thuộc tính đang lưu',increaseTimes:'Lần nâng cấp',attrValue:'Giá trị thuộc tính',expireTime:'Hết hạn',kindName:'Tên riêng',desc:'Mô tả riêng'};modal(row.instance.kindName||row.name,`<div class="detail-hero">${itemImage(row,'large')}<div>${badge('',typeNames[row.type]||row.type)}<h3 style="margin-top:10px">${esc(row.instance.kindName||row.name)}</h3><small>Nhân vật #${pid} · ${source==='team'?'Vị trí':'Ô túi'} ${esc(slot)}</small></div></div><p class="muted" style="font-size:12px">Các thuộc tính riêng và tiến độ nâng cấp của món đồ.</p><table class="key-values">${Object.entries(row.instance).map(([k,v])=>`<tr><td>${esc(names[k]||k)}</td><td><code>${esc(k==='expireTime'?time(v/1000):typeof v==='object'?JSON.stringify(v):typeof v==='number'?new Intl.NumberFormat('vi-VN',{maximumSignificantDigits:10}).format(v):v)}</code></td></tr>`).join('')}</table><div class="form-footer">${btn('Hồ sơ nhân vật','left','player',`data-id="${pid}"`)}${btn('Thông số gốc','box','item',`data-id="${row.id}"`)}${btn('Cấp thêm','gift','grant',`data-player="${pid}" data-item="${row.id}"`,'primary')}</div>`,'TRẠNG THÁI VẬT PHẨM · #'+row.id)}

async function grantEditor(pid,item){const loot=[{entityId:Number(item)||119,count:1,extra:{}}];await prime(loot);modal('Cấp vật phẩm',form(`${field('Player ID','player','number',pid||'','ID có trong mục Người chơi.','min="1" required')}<div class="form-section">Phần thưởng</div>${rewardSet('grantRewards',loot)}<div class="notice">${icon('info')}<span>Thưởng được lưu vào hồ sơ thật. ID 100 là kinh nghiệm, ID 98 là điểm VIP; tướng trùng chuyển thành mảnh theo luật game.</span></div>`,'Cấp vào nhân vật'));submitForm(async f=>api('/admin/api',{action:'grant_items',player:Number(f.elements.player.value),rewards:readRewards('#grantRewards')}))}
async function resourceEditor(id){const d=await api('/admin/players/'+id),p=d.player;modal('Chỉnh tài nguyên · '+p.name,form(`<div class="form-grid">${['level','vipLevel','gem','coin','actionPoint','skillPoint'].map((k,i)=>field(['Cấp người chơi','Cấp VIP','Gem','Coin','Thể lực','Điểm kỹ năng'][i],k,'number',k==='vipLevel'?p.vip:p[k],'',`min="${k==='level'?1:0}" max="${k==='level'?100:k==='vipLevel'?16:1000000000}" required`)).join('')}</div><div class="notice">${icon('info')}<span>Các số trên là giá trị mới, không phải số cộng thêm. Thay đổi được ghi vào nhật ký và gửi tới nhân vật đang online.</span></div>`));submitForm(async f=>api('/admin/api',{action:'player_update',player:Number(id),expected:Object.fromEntries(['level','vipLevel','gem','coin','actionPoint','skillPoint'].map(k=>[k,k==='vipLevel'?p.vip:p[k]])),values:Object.fromEntries(Object.entries(values(f)).map(([k,v])=>[k,Number(v)]))}))}
async function mailEditor(pid){await prime([{entityId:119}]);modal('Gửi thư hệ thống',form(`<label class="check"><input type="checkbox" name="all" id="mailAll"> Gửi cho tất cả người chơi hiện có</label><div id="mailTarget">${field('Player ID','player','number',pid||'','','min="1" required')}</div>${field('Tiêu đề','title','text','','','maxlength="100" required')}<label class="field">Nội dung<textarea name="body" maxlength="2000"></textarea></label><div class="form-section">Vật phẩm đính kèm</div>${rewardSet('mailRewards',[{entityId:119,count:1}])}`,'Gửi thư'));$('#mailAll').onchange=e=>{ $('#mailTarget').hidden=e.target.checked;$('[name=player]',$('#editForm')).required=!e.target.checked };submitForm(async f=>{const v=values(f);await api('/admin/api',{action:'send_mail',player:Number(v.player),all:f.elements.all.checked,title:v.title,body:v.body,rewards:readRewards('#mailRewards')})})}
async function codeEditor(code){const c=state.giftcodes.find(r=>r.code===code),loot=c?.rewards||[];await prime(loot);modal(c?'Chỉnh giftcode':'Tạo giftcode',form(`<div class="form-grid">${field('Mã giftcode','code','text',c?.code||'DB2_'+Math.random().toString(36).slice(2,8).toUpperCase(),'Mỗi nhân vật nhận một lần.',`${c?'readonly':''} required maxlength="64"`)}${field('Tổng lượt sử dụng','max_uses','number',c?.max_uses||100,'Đã dùng: '+(c?.used||0),'min="1" required')}${field('Hạn dùng · UTC+7','expires','datetime-local',toInput(c?.expires||Date.now()/1000+30*86400),'','required')}${field('Gem bổ sung','gem','number',c?.gem||0,'Ngoài danh sách vật phẩm bên dưới.','min="0" max="1000000000" required')}</div><label class="check"><input type="checkbox" name="enabled" ${c?.enabled!==false?'checked':''}> Cho phép đổi mã</label><div class="form-section">Vật phẩm tặng kèm</div>${rewardSet('codeRewards',loot)}`));submitForm(async f=>{const v=values(f);await api('/admin/api',{action:'giftcode_save',code:v.code,gem:Number(v.gem),max_uses:Number(v.max_uses),expires:fromInput(v.expires),enabled:f.elements.enabled.checked,rewards:readRewards('#codeRewards')})})}
async function poolEditor(id){const p=state.pools.find(x=>x.id===state.pool),r=p.entries.find(r=>r.entityId===Number(id));await prime([r||{entityId:119}]);modal(r?'Chỉnh phần thưởng gacha':'Thêm phần thưởng gacha',form(`<div class="notice">${icon('info')}<span>Pool ${state.pool} · Mỗi lượt chọn 1 dòng theo trọng số. Tướng cần số lượng 1.</span></div>${rewardSet('poolReward',[r||{entityId:119,count:1,extra:{}}])}${field('Trọng số','weight','number',r?.weight||100,'Tỉ lệ được tính lại theo tổng trọng số của toàn pool.','min="1" max="1000000000" required')}`));$('#poolReward+button')?.remove();$('.reward-row [data-act=reward-remove]',$('#poolReward'))?.remove();submitForm(async f=>{const r=readRewards('#poolReward')[0];if(!r)throw Error('Cần một phần thưởng');await api('/admin/api',{action:'gacha_entry',pool:state.pool,entity:r.entityId,count:r.count,star:r.extra.star||1,weight:Number(f.elements.weight.value)})})}
async function wheelEditor(){if(!state.wheel.length){const d=await api('/admin/gacha');state.wheel=d.wheelPrizes;cacheItems(d.wheelPrizes.map(x=>x.item))}modal('Bảng 8 ô vòng quay',form(`<div class="notice">${icon('info')}<span>Dùng chung cho năm vòng quay và phần thưởng quay điểm. Giữ đúng 8 ô để khớp client. Lượt đã quay ở vòng đặc biệt vẫn được giữ.</span></div>${state.wheel.map((r,i)=>`<div class="reward-group"><div class="form-section">Ô ${i+1}</div>${rewardSet('wheel_'+i,[r])}${field('Trọng số','weight_'+i,'number',r.weight,'','min="1" required')}</div>`).join('')}`));$$('.reward-group [data-act=reward-add],.reward-group [data-act=reward-remove]').forEach(e=>e.remove());submitForm(async f=>api('/admin/api',{action:'wheel_prizes',entries:state.wheel.map((_,i)=>({...readRewards('#wheel_'+i)[0],weight:Number(f.elements['weight_'+i].value)}))}))}
function confirmAction(title,text,body){modal(title,form(`<p class="muted">${esc(text)}</p>`,'Xác nhận'));submitForm(async()=>api('/admin/api',body))}
async function action(el){const a=el.dataset.act,id=el.dataset.id;if(a==='go'){location.hash=el.dataset.route;return}if(a==='reload'){await load();return}if(a==='page'){state.page=Number(el.dataset.page);await load();return}if(a==='modal-close'){$('#modal').close();return}if(a==='reward-browse'){const input=$('[data-picker-search]',el.closest('.item-picker'));input.focus();await showPicker(input,'');return}if(a==='reward-add'){await prime([{entityId:119}]);const root=$('#'+el.dataset.target);root.insertAdjacentHTML('beforeend',rewardRow());return}if(a==='reward-remove'){el.closest('.reward-row').remove();return}if(a==='item'){await itemDetail(id);return}if(a==='player'){await playerDetail(id);return}if(a==='instance'){instanceDetail(el.dataset.source,el.dataset.slot);return}if(a==='grant'){await grantEditor(el.dataset.player,el.dataset.item);return}if(a==='player-update'){await resourceEditor(id);return}if(a==='mail'){await mailEditor(el.dataset.player);return}if(a==='gm'){confirmAction(el.dataset.enabled==='true'?'Cấp quyền GM':'Thu hồi quyền GM','Thay đổi quyền dùng các thao tác GM riêng cho nhân vật #'+id+'.',{action:'set_gm',player:Number(id),enabled:el.dataset.enabled==='true'});return}if(a==='event-new'||a==='event-edit'){await eventEditor(id);return}if(a==='template-edit'){await templateEditor(id);return}if(a==='event-tab'){state.eventTab=el.dataset.tab;state.q='';state.status='';await load();return}if(a==='event-toggle'){const e=state.events.find(e=>e.id===id);await api('/admin/api',{action:'event_toggle',id,enabled:e.enabled===false});$('#modal').close();toast('Đã cập nhật trạng thái sự kiện.');await load();return}if(a==='event-delete'){confirmAction('Lưu trữ sự kiện','Sự kiện ngừng hoạt động. Lịch sử nhận thưởng được giữ và ID này không được tái sử dụng.',{action:'event_delete',id});return}if(a==='month'){state.month=new Date(state.month.getFullYear(),state.month.getMonth()+Number(el.dataset.step),1);await load();return}if(a==='month-today'){state.month=new Date(new Date().toLocaleString('en-US',{timeZone:'Asia/Ho_Chi_Minh'}));await load();return}if(a==='calendar-day'){const start=Number(el.dataset.start),end=start+86400,d=await api('/admin/calendar?start='+start+'&end='+end);modal('Sự kiện · '+date(start),d.items.map(e=>`<button class="btn full" data-act="${e.source==='builtin'?'template-edit':'event-edit'}" data-id="${esc(e.id)}" style="margin-bottom:10px">${esc(e.name)} · ${shortTime(e.start)}</button>`).join(''));return}if(a==='pool'){state.pool=Number(id);await load();return}if(a==='pool-add'||a==='pool-edit'){await poolEditor(id);return}if(a==='pool-remove'){confirmAction('Xóa phần thưởng khỏi pool','Tỉ lệ các mục còn lại sẽ được tính lại. Nếu xóa mục cuối cùng, pool trở về bảng mặc định.',{action:'gacha_remove',pool:state.pool,entity:Number(id)});return}if(a==='pool-reset'){confirmAction('Khôi phục bảng drop gốc','Xóa pool tùy chỉnh #'+id+' và dùng lại bảng drop cùng bảo hiểm mặc định.',{action:'gacha_reset',pool:Number(id)});return}if(a==='wheel'){await wheelEditor();return}if(a==='code-new'||a==='code-edit'){await codeEditor(id);return}if(a==='audit-detail'){const r=state.audit.find(r=>r.id===Number(id));modal(actionName(r.action),`<p class="muted">${time(r.created)} · Bản ghi #${r.id}</p><pre>${esc(JSON.stringify(r.parsed,null,2))}</pre>`);return}if(a==='copy'){try{await navigator.clipboard.writeText(el.dataset.value);toast('Đã sao chép '+el.dataset.value)}catch{toast('ID: '+el.dataset.value)}return}}
function hidePicker(input){clearTimeout(input._timer);input._pickerRequest=(input._pickerRequest||0)+1;const list=$('.picker-results',input.closest('.item-picker'));if(list)list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant')}
function chooseReward(option){const row=option.closest('.reward-row'),id=Number(option.dataset.pickerId),input=$('[data-picker-search]',row),it=known(id);clearTimeout(input._timer);input._pickerRequest=(input._pickerRequest||0)+1;$('.reward-id',row).value=id;input.setCustomValidity('');input.value=it.name+' · #'+id;$('[data-reward-preview]',row).innerHTML=selectedReward(it);$('.reward-star',row).disabled=it.type!=='role';if(it.type==='role')$('.reward-count',row).value=1;hidePicker(input);input.focus()}
async function showPicker(input,query=input.value){
 const list=$('.picker-results',input.closest('.item-picker')),request=(input._pickerRequest||0)+1;input._pickerRequest=request;list.hidden=false;input.setAttribute('aria-expanded','true');list.innerHTML='<p class="picker-message" role="status">Đang tìm vật phẩm…</p>';
 try{const d=await api('/admin/catalog?limit=10&q='+encodeURIComponent(query));if(!input.isConnected||request!==input._pickerRequest)return;cacheItems(d.items);input.removeAttribute('aria-activedescendant');input._pickerIndex=-1;list.innerHTML=d.items.map((it,i)=>`<button type="button" role="option" aria-selected="false" tabindex="-1" id="${list.id}-option-${i}" class="picker-result" data-picker-id="${it.id}">${itemImage(it,'mini')}<span><strong>${esc(it.name)}</strong><small>#${it.id} · ${esc(typeNames[it.type]||it.type)}</small></span></button>`).join('')||'<p class="picker-message" role="status">Không tìm thấy vật phẩm. Thử tên hoặc ID khác.</p>';list.hidden=false;input.setAttribute('aria-expanded','true')}
 catch(err){if(!input.isConnected||request!==input._pickerRequest)return;list.innerHTML='<p class="picker-message" role="alert">Không tải được danh mục. Bấm tìm để thử lại.</p>';toast(err.message,true)}
}
document.addEventListener('click',e=>{const option=e.target.closest('[data-picker-id]');if(option){e.preventDefault();chooseReward(option);return}const el=e.target.closest('[data-act]');if(el){e.preventDefault();action(el).catch(err=>toast(err.message,true))}if(!e.target.closest('.item-picker'))$$('[data-picker-search]').forEach(hidePicker)});
document.addEventListener('input',e=>{if(!e.target.matches('[data-picker-search]'))return;const input=e.target,row=input.closest('.reward-row');input.setCustomValidity('Chọn vật phẩm từ danh sách gợi ý.');$('.reward-id',row).value='';$('[data-reward-preview]',row).innerHTML=selectedReward(null);input._pickerRequest=(input._pickerRequest||0)+1;clearTimeout(input._timer);input._timer=setTimeout(()=>showPicker(input),220)});
document.addEventListener('keydown',e=>{if(!e.target.matches('[data-picker-search]'))return;const input=e.target,list=$('.picker-results',input.closest('.item-picker'));if(e.key==='Escape'&&!list.hidden){e.preventDefault();e.stopPropagation();hidePicker(input);return}if(!['ArrowDown','ArrowUp','Enter'].includes(e.key))return;if(list.hidden){if(e.key!=='Enter'){e.preventDefault();showPicker(input,'')}return}e.preventDefault();const options=$$('[data-picker-id]',list);if(!options.length)return;if(e.key==='Enter'){chooseReward(options[Math.max(0,input._pickerIndex||0)]);return}input._pickerIndex=((input._pickerIndex??-1)+(e.key==='ArrowDown'?1:-1)+options.length)%options.length;options.forEach((o,i)=>o.setAttribute('aria-selected',i===input._pickerIndex?'true':'false'));const active=options[input._pickerIndex];input.setAttribute('aria-activedescendant',active.id);active.scrollIntoView({block:'nearest'})});
document.addEventListener('focusout',e=>{if(e.target.matches('[data-picker-search]')){const input=e.target;setTimeout(()=>{if(input.isConnected&&!input.closest('.item-picker').contains(document.activeElement))hidePicker(input)},0)}});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&e.target.parentElement?.classList.contains('item-image')){const parent=e.target.parentElement;e.target.remove();parent.insertAdjacentHTML('beforeend',icon('box'));parent.classList.add('image-unavailable')}},true);
