$('#loginForm').onsubmit=async e=>{e.preventDefault();state.token=$('#token').value.trim();const b=$('button[type=submit]',e.currentTarget);b.disabled=true;$('#loginError').textContent='';try{await api('/admin/overview');if($('#remember').checked)sessionStorage.setItem('db2.admin.token',state.token);$('#token').value='';$('#login').hidden=true;$('#app').hidden=false;state.route=paths[location.hash.slice(1)]?location.hash.slice(1):'overview';await load()}catch(err){$('#loginError').textContent=err.message}finally{b.disabled=false}};
